import { ISettingsOption } from '@game-studio/settings';
import { IProvideChatColoursPayload } from '@game-studio/shell-connection';
import { CHAT_COLOURS } from '@game-studio/utilities';

export interface IChatSettingsOption extends ISettingsOption {
    value: string;
}

export function mappedChatColours(colours: IProvideChatColoursPayload[]): IChatSettingsOption[] {
    const coloursArray: IChatSettingsOption[] = [];
    colours.forEach(colour => {
        const mappedColour = {
            text: colour.name,
            value: colour.hexColour
        };
        coloursArray.push(mappedColour);
    });
    return coloursArray;
}

export const chatColoursBackup: IChatSettingsOption[] = mappedChatColours(CHAT_COLOURS);